// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(uint256 amt) public {
        amt = bound(amt, 1 wei, 1 ether);

        // extra funding so a double payout is even possible for the mutant
        vm.deal(address(c), 2 ether);

        Attack atk = new Attack();
        vm.deal(address(atk), amt);

        // attacker deposits amt, then withdraws re-entrantly (first withdraw)
        atk.go(c, amt);

        // Rule: the contract holds exactly its original funding after paying out
        // the recorded balance exactly once — no double payout may occur.
        assertTrue(address(c).balance == 2 ether);
    }
}

contract Attack {
    keepMyEther c;

    function go(keepMyEther _c, uint256 amt) external {
        c = _c;
        // deposit amt into c via the payable fallback
        address(_c).call{value: amt}("");
        // withdraw, re-entering from receive()
        _c.withdraw();
    }

    receive() external payable {
        // re-enter withdraw; ignore failure (it must fail under the correct lock)
        try c.withdraw() {} catch {}
    }
}
